_EVIDENCE_REFS = frozenset(
    {
        "failing_result",
        "kind_detail",
        "metric_trend",
        "check_history",
        "sibling_checks",
        "same_asset_siblings",
        "upstream_pipeline_run",
        "downstream_blast_radius",
    }
)

_MONITOR_KINDS = frozenset({"freshness", "volume", "schema_drift", "anomaly"})

